CREATE INDEX IF NOT EXISTS "domain_events_m43_cutover_run_occurred_idx" ON "domain_events" USING btree ("run_id","occurred_at") WHERE "domain_events"."kind" = 'run.failed' AND "domain_events"."payload"->>'reason' = 'legacy_steps_engine_3_cutover' AND "domain_events"."payload"->>'source' = 'upgrade_cutover';--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "domain_events_m43_cutover_task_occurred_idx" ON "domain_events" USING btree ("task_id","occurred_at") WHERE "domain_events"."kind" = 'run.failed' AND "domain_events"."payload"->>'reason' = 'legacy_steps_engine_3_cutover' AND "domain_events"."payload"->>'source' = 'upgrade_cutover' AND "domain_events"."task_id" IS NOT NULL;